import 'dart:convert';
import 'dart:typed_data';
import 'package:flutter/material.dart';

/// Chứa dữ liệu ảnh nhúng trực tiếp (Base64) - Đảm bảo siêu nét và 100% không bao giờ mất ảnh
class AppAssetImages {
  AppAssetImages._();

  static final Uint8List logoBytes = base64Decode(
    '',
  );
  static final Uint8List splashBgBytes = base64Decode(
    '',
  );
  static final Uint8List glasshouseBytes = base64Decode(
    '',
  );

  /// Widget hiển thị Logo DaLatTrip (Đã bỏ dòng chữ nhỏ, chỉ còn đỉnh núi + chữ DALATTRIP)
  static Widget logo({
    double? height,
    double? width,
    BoxFit fit = BoxFit.contain,
  }) {
    return Image.memory(
      logoBytes,
      height: height,
      width: width,
      fit: fit,
      filterQuality: FilterQuality.high,
    );
  }

  /// Widget hiển thị Ảnh nền đồi thông và nhà thờ Đà Lạt siêu nét (Ảnh vào & Home)
  static Widget splashBg({
    BoxFit fit = BoxFit.cover,
    Alignment alignment = Alignment.center,
    double? width,
    double? height,
  }) {
    return Image.memory(
      splashBgBytes,
      fit: fit,
      alignment: alignment,
      width: width,
      height: height,
      filterQuality: FilterQuality.high,
    );
  }

  /// Widget hiển thị Ảnh nhà lồng kính & đồi thông chân trang
  static Widget glasshouseBg({
    BoxFit fit = BoxFit.cover,
    Alignment alignment = Alignment.center,
    double? width,
    double? height,
  }) {
    return Image.memory(
      glasshouseBytes,
      fit: fit,
      alignment: alignment,
      width: width,
      height: height,
      filterQuality: FilterQuality.high,
    );
  }
}
